101	  _pruneTickets() {
102	    const now = this.now();
103	    for (const [id, ticket] of this.tickets) if (ticket.expiresAt <= now) this.tickets.delete(id);
104	  }
105	
106	  consume(value, principal, origin) {
107	    this._pruneTickets();
108	    const split = typeof value === 'string' ? value.indexOf('.') : -1;
109	    const id = split > 0 ? value.slice(0, split) : '';
110	    const secret = split > 0 ? value.slice(split + 1) : '';
111	    const found = this.tickets.get(id);
112	    const presented = digest(secret);
113	    const valid = found && found.expiresAt > this.now()
114	      && timingSafeEqual(presented, found.hash)
115	      && found.sessionId === principal?.sessionId && found.credentialId === principal?.credentialId
116	      && found.origin === origin && this._liveAuthorized(principal, origin, found.repoId);
117	    if (!valid) return null;
118	    this.tickets.delete(id);
119	    return { id, repoId: found.repoId };
120	  }
121	
122	  open({ ticket, principal, origin, cursor }, res) {
123	    if (!this.accepting) return response(503, 'temporarily_unavailable');
124	    let lease = null;
125	    if (this.acquireConnection) {
126	      lease = this.acquireConnection(principal);
127	      if (!lease?.ok) {
128	        try { this._audit('stream_refused', principal, origin, { reason: 'principal_connection_limit' }); }
129	        catch { return response(503, 'temporarily_unavailable'); }
130	        return { ...response(429, 'rate_limited'), headers: { 'retry-after': String(lease?.retryAfter ?? 1) } };
131	      }
132	    }
133	    if (this.activeConnections >= this.maxConnections) {
134	      if (lease && this.releaseConnection) this.releaseConnection(principal);
135	      try { this._audit('stream_refused', principal, origin, { reason: 'connection_limit' }); }
136	      catch { return response(503, 'temporarily_unavailable'); }
137	      return { ...response(429, 'rate_limited'), headers: { 'retry-after': '1' } };
138	    }
139	    const grant = this.consume(ticket, principal, origin);
140	    if (!grant) {
141	      if (lease && this.releaseConnection) this.releaseConnection(principal);
142	      try { this._audit('stream_refused', principal, origin, { reason: 'invalid_ticket' }); }
143	      catch { return response(503, 'temporarily_unavailable'); }
144	      return response(principal ? 403 : 401, principal ? 'forbidden' : 'unauthenticated');
145	    }
146	
147	    let snapshot;
148	    try { snapshot = this.coordination.snapshot(); }
149	    catch {
150	      try { this._audit('stream_refused', principal, origin, { repoId: grant.repoId, reason: 'snapshot_unavailable' }); }
151	      catch { if (lease && this.releaseConnection) this.releaseConnection(principal); return response(503, 'temporarily_unavailable'); }
152	      if (lease && this.releaseConnection) this.releaseConnection(principal);
153	      return response(503, 'temporarily_unavailable');
154	    }
155	    const boundary = snapshot.lastSeq;
156	    const requested = cursor == null || cursor === '' ? null : Number(cursor);
157	    if (requested !== null && (!Number.isSafeInteger(requested)
158	      || requested < Math.max(0, boundary - this.replayLimit) || requested > boundary)) {
159	      try { this._audit('stream_snapshot_required', principal, origin, {
160	        repoId: grant.repoId, requestedCursor: Number.isSafeInteger(requested) ? requested : null, boundary,
161	      }); } catch { if (lease && this.releaseConnection) this.releaseConnection(principal); return response(503, 'temporarily_unavailable'); }
162	      if (lease && this.releaseConnection) this.releaseConnection(principal);
163	      return response(409, 'snapshot_required', { snapshotCursor: boundary });
164	    }
165	
166	    const streamId = randomUUID();
167	    let next = requested === null ? boundary + 1 : requested + 1;
168	    let closed = false;
169	    let timer;
170	    const frame = (type, cursorValue, eventId, payload) => ({
171	      schemaVersion: 1, streamId, cursor: cursorValue, eventId,
172	      provenance: 'coordination-authority', occurrenceTrust: 'authoritative',
173	      contentTrust: type === 'snapshot' ? 'mixed' : this._contentTrust(payload),
174	      resource: { repoId: grant.repoId }, type, payload,
175	    });
176	    const encode = (type, id, value) => `id: ${id}\nevent: ${type}\ndata: ${JSON.stringify(value)}\n\n`;
177	    const disconnect = (kind = 'stream_disconnected') => {
178	      if (closed) return;
179	      closed = true;
180	      this.activeConnections -= 1;
181	      if (timer) clearInterval(timer);
182	      this.connections.delete(closeForShutdown);
183	      if (lease && this.releaseConnection) { this.releaseConnection(principal); lease = null; }
184	      try { this._audit(kind, principal, origin, { repoId: grant.repoId, streamId, cursor: next - 1 }); } catch { /* never turn stream loss into fleet control */ }
185	    };
186	    const closeForShutdown = () => { try { res.write('event: shutdown\ndata: {"reconnect":true}\n\n'); } catch {} disconnect('stream_shutdown'); try { res.end(); } catch {} };
187	    const send = (event) => {
188	      const value = frame('coordination', event.seq, `coordination:${event.seq}`, event);
189	      const encoded = encode('coordination', event.seq, value);
190	      if (Buffer.byteLength(encoded) > this.maxFrameBytes
191	        || (res.writableLength ?? 0) + Buffer.byteLength(encoded) > this.maxBufferedBytes) {
192	        const lag = frame('lag', next - 1, `lag:${streamId}`, { code: 'backpressure', reconnect: true });
193	        const control = encode('lag', next - 1, lag);
194	        if (Buffer.byteLength(control) <= this.maxControlFrameBytes) res.write(control);
195	        disconnect('stream_backpressure_disconnect');
196	        res.end();
197	        return false;
198	      }
199	      const accepted = res.write(encoded);
200	      next = event.seq + 1;
201	      if (accepted === false) {
202	        const lag = frame('lag', next - 1, `lag:${streamId}`, { code: 'backpressure', reconnect: true });
203	        const control = encode('lag', next - 1, lag);
204	        if (Buffer.byteLength(control) <= this.maxControlFrameBytes) res.write(control);
205	        disconnect('stream_backpressure_disconnect');
206	        res.end();
207	        return false;
208	      }
209	      return true;
210	    };
211	
212	    let initial = null;
213	    if (requested === null) {
214	      const value = frame('snapshot', boundary, `snapshot:${boundary}`, { seq: boundary, snapshot: clone(snapshot) });
215	      initial = encode('snapshot', boundary, value);
216	      const initialBytes = Buffer.byteLength(initial);
217	      if (initialBytes > this.maxFrameBytes
218	        || (res.writableLength ?? 0) + initialBytes > this.maxBufferedBytes) {
219	        try { this._audit('stream_refused', principal, origin, { repoId: grant.repoId, reason: 'snapshot_too_large', boundary }); }
220	        catch { if (lease && this.releaseConnection) this.releaseConnection(principal); return response(503, 'temporarily_unavailable'); }
221	        if (lease && this.releaseConnection) this.releaseConnection(principal);
222	        return response(503, 'temporarily_unavailable', { snapshotCursor: boundary });
223	      }
224	    }
225	    try { this._audit('stream_connected', principal, origin, { repoId: grant.repoId, streamId, cursor: requested ?? boundary }); }
226	    catch { if (lease && this.releaseConnection) this.releaseConnection(principal); return response(503, 'temporarily_unavailable'); }
227	    this.activeConnections += 1;
228	    this.connections.add(closeForShutdown);
229	    const pump = () => {
230	      if (closed) return;
231	      try {
232	        if (!this._liveAuthorized(principal, origin, grant.repoId)) {
233	          disconnect('stream_authorization_lost');
234	          try { res.end(); } catch { /* connection is already unusable */ }
235	          return;
236	        }
237	        for (const event of this.coordination.events(next, this.maxEventsPerPump)) {
238	          if (!this._liveAuthorized(principal, origin, grant.repoId)) {
239	            disconnect('stream_authorization_lost');
240	            try { res.end(); } catch { /* connection is already unusable */ }
241	            return;
242	          }
243	          if (!send(event)) break;
244	        }
245	      } catch {
246	        disconnect('stream_read_failed');
247	        try { res.end(); } catch { /* connection is already unusable */ }
248	      }
249	    };
250	    let headersStarted = false;
251	    try {
252	      res.on?.('close', () => disconnect());
253	      res.on?.('error', () => disconnect());
254	      res.writeHead(200, {
255	        'content-type': 'text/event-stream; charset=utf-8', 'cache-control': 'no-store',
256	        connection: 'keep-alive', 'x-accel-buffering': 'no',
257	        'access-control-allow-origin': origin, 'access-control-allow-credentials': 'true',
258	        vary: 'Origin', 'x-content-type-options': 'nosniff',
259	      });
260	      headersStarted = true;
261	      if (initial && res.write(initial) === false) {
262	        const lag = frame('lag', next - 1, `lag:${streamId}`, { code: 'backpressure', reconnect: true });
263	        const control = encode('lag', next - 1, lag);
264	        if (Buffer.byteLength(control) <= this.maxControlFrameBytes) res.write(control);
265	        disconnect('stream_backpressure_disconnect');
266	        res.end();
267	        return null;
268	      }
269	      pump();
270	      if (!closed) {
271	        timer = setInterval(pump, this.pollMs);
272	        timer.unref?.();
273	      }
274	    } catch {
275	      disconnect('stream_setup_failed');
276	      if (headersStarted) {
277	        try { res.end(); } catch { /* connection is already unusable */ }
278	        return null;
279	      }
280	      return response(503, 'temporarily_unavailable');
281	    }
282	    return null;
283	  }
284	
285	  shutdown() { this.accepting = false; for (const close of [...this.connections]) close(); }
286	
287	  _contentTrust(event) {
288	    const kind = event?.kind ?? '';
289	    if (kind === 'scratch.claimed') return 'claimed';
290	    if (kind === 'scratch.fact_posted') return event?.payload?.grounding ?? 'observed';
291	    if (kind.startsWith('knowledge.')) return event?.payload?.grounding ?? 'derived';
292	    if (kind === 'web.audit') return 'observed';
293	    return 'authoritative';
294	  }
